            h_lines.append(r)

    # Find vertical lines (cols that are mostly line_color)
    v_lines = []
    for c in range(cols):
        count = sum(1 for r in range(rows) if grid[r][c] == line_color)
        if count > rows * 0.5:  # More than half are line_color
            v_lines.append(c)

    # Create output
    output = [row[:] for row in grid]

