    def get_cell_idx(r, c):
        # Find which cell row
        cell_r = -1
        for i, hr in enumerate(h_lines):
            if r < hr:
                cell_r = i
                break
        if cell_r == -1:
            cell_r = len(h_lines)

        # Find which cell col
        cell_c = -1
        for j, vc in enumerate(v_lines):
            if c < vc:
                cell_c = j
                break
        if cell_c == -1:
            cell_c = len(v_lines)

        return cell_r, cell_c

    # Fill cells with checkerboard pattern
    # Define cell boundaries
    h_starts = [0] + [h + 1 for h in h_lines]
