            fill_val = 3 if (i + j) % 2 == 0 else 4

            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    if output[r][c] == 0:
                        output[r][c] = fill_val

    # Fill holes in grid lines
    for r in h_lines:
