                cell_r, cell_c = get_cell_idx(r, c)
                # For horizontal line, check cell above or below
                # Prefer the one with valid range
                if cell_r > 0:
                    ref_r, ref_c = cell_r - 1, cell_c
                else:
                    ref_r, ref_c = cell_r, cell_c
                fill_val = 3 if (ref_r + ref_c) % 2 == 0 else 4
                output[r][c] = fill_val

